// Arma las variables del template a partir de cada negocio.
// AJUSTAR nombre del template y de las variables una vez que exista
// un template real aprobado por Meta (GET /message-template).

const TEMPLATE_NAME = 'PENDIENTE_nombre_del_template_aprobado';

return $input.all().map(item => {
  const negocio = item.json;
  const nombre = negocio.Contact?.name || '';
  const numero = negocio.Contact?.number || negocio.Contact?.phone || '';

  return {
    json: {
      negocioId: negocio.id,
      number: numero,
      templateName: TEMPLATE_NAME,
      manualVariables: { '{{1}}': nombre },
    },
  };
}).filter(i => i.json.number); // nunca mandar sin numero confirmado
